static void Patch32(const std::filesystem::path &p, size_t offset, uint32_t value) {
  std::fstream file(p, std::ios::binary | std::ios::in | std::ios::out);
  std::array<char, 4> bytes{};
  for (unsigned i = 0; i < 4; ++i)
    bytes[i] = char(value >> (i * 8));
